import java.io.*;
import java.util.*;

public class Cards {
    public static long MOD = 998244353;
    public static long[][] stirling;
    public static void main(String[] args) throws IOException{
        BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(f.readLine());
        long n = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        long p = modInverse(m, MOD);
        // Compute Stirling numbers with swapped recurrence order
        stirling = new long[5001][5001];
        stirling[0][0] = 1;
        for(int i = 1; i < 5001; i++){
            for(int j = 1; j < 5001; j++){
                stirling[i][j] = (j * stirling[i-1][j]) % MOD;
                stirling[i][j] = (stirling[i][j] + stirling[i-1][j-1]) % MOD;
            }
        }
        long ans = 0;
        long prob = 1;
        long val = 1;
        // Forward loop: i from 0 to k-1
        for(int i = 0; i < k; i++){
            val = (val * (n - i)) % MOD;
            prob = (prob * p) % MOD;
            ans = (ans + ((val * prob) % MOD) * stirling[k][i+1]) % MOD;
        }
        System.out.println(ans);
    }

    public static long modInverse(long x, long p){
        return power(x, p-2, p);
    }

    public static long power(long x, long y, long p){
        long res = 1;
        x = x % p;
        while (y > 0) {
            if (y % 2 == 1)
                res = (res * x) % p;
            y = y >> 1;
            x = (x * x) % p;
        }
        return res;
    }
}
